// Cancel a booking and offer the freed slot to the first student waiting for it (BR-09, lesson 10.1).
import { BookingError } from './service.js';
import { offerNext, OFFER_MINUTES } from '../rules/waitlist.js';

export const slotKey = (b) => b.lab + ' ' + b.date + ' ' + b.start + '-' + b.end;

// waitlists: a Map from slotKey to a queue [{ userId }]; userId is the student's e-mail address.
export async function cancelBooking({ repo, waitlists, mailer, now = () => new Date() }, id) {
  const booking = await repo.remove(id);
  if (!booking) throw new BookingError('NOT_FOUND');
  const key = slotKey(booking);
  const { offer, queue } = offerNext(waitlists.get(key) ?? [], now());
  waitlists.set(key, queue);
  if (offer) {
    await mailer.send({ to: offer.userId, subject: 'A seat is free: ' + key + ' (answer within ' + OFFER_MINUTES + ' minutes)' });
  }
  return { cancelled: booking.id, offeredTo: offer ? offer.userId : null };
}

import { parseTime } from './time.js';

export const OPEN = 7 * 60;          // 07:00
export const CLOSE = 21 * 60;        // 21:00
export const STEP = 30;              // BR-04: 30-minute grid
export const MAX_MINUTES = 240;      // Lite-1: at most 4 hours
export const MAX_DAYS_AHEAD = 14;    // BR-05: at most 14 days ahead
export const APPROVAL_SEATS = 30;    // BR-06: more than 30 seats needs approval

export function checkSlot(start, end) {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % STEP !== 0 || e % STEP !== 0) return { ok: false, code: 'OFF_GRID' };
  if (e <= s) return { ok: false, code: 'END_BEFORE_START' };
  if (s < OPEN || e > CLOSE) return { ok: false, code: 'OUTSIDE_HOURS' };
  if (e - s > MAX_MINUTES) return { ok: false, code: 'TOO_LONG' };
  return { ok: true, minutes: e - s };
}

export function isWithinBookingWindow(daysAhead) {
  return Number.isInteger(daysAhead) && daysAhead >= 0 && daysAhead <= MAX_DAYS_AHEAD;
}

export function needsApproval({ seats, role }) {
  if (!Number.isInteger(seats) || seats < 1) {
    throw new RangeError('seats must be a positive integer, got ' + seats);
  }
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > APPROVAL_SEATS;
}

export function createBooking({ lab, seats, role, start, end }) {
  const slot = checkSlot(start, end);
  if (!slot.ok) throw new Error(slot.code);
  return {
    lab,
    start,
    end,
    minutes: slot.minutes,
    status: needsApproval({ seats, role }) ? 'PENDING' : 'CONFIRMED',
  };
}

// Share of opening hours already booked, added booking by booking (0..1).
export function usageRate(bookings) {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / (CLOSE - OPEN);
  return rate;
}

// Convert between "HH:MM" and minutes since 00:00.
export function parseTime(text) {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) throw new RangeError('Time out of range: ' + text);
  return h * 60 + min;
}

export function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

// BR-09 — waitlist for a taken slot (Chapter 10, built test-first in lesson 10.1).
export const WAITLIST_MAX = 3;     // at most 3 students wait for one slot
export const OFFER_MINUTES = 30;   // a freed slot is held for the first in line for 30 minutes

const refuse = (code) => ({ ok: false, code });
const minutesLater = (date, minutes) => new Date(date.getTime() + minutes * 60 * 1000);

// queue: [{ userId }], oldest first. Never changes the queue it is given; returns a new one.
export function joinWaitlist(queue, { userId, holderId }) {
  if (userId === holderId) return refuse('IS_HOLDER');
  if (queue.some((w) => w.userId === userId)) return refuse('ALREADY_WAITING');
  if (queue.length >= WAITLIST_MAX) return refuse('WAITLIST_FULL');
  const next = [...queue, { userId }];
  return { ok: true, position: next.length, queue: next };
}

// The slot was freed at `now`: offer it to the first student in line.
export function offerNext(queue, now) {
  if (queue.length === 0) return { offer: null, queue: [] };
  const [first, ...rest] = queue;
  return { offer: { userId: first.userId, expiresAt: minutesLater(now, OFFER_MINUTES) }, queue: rest };
}

export function acceptOffer(offer, now) {
  return now < offer.expiresAt ? { ok: true } : refuse('OFFER_EXPIRED');
}

// A FAKE mailer: a small working implementation that keeps sent mail in memory instead of calling a provider.
export function createFakeMailer() {
  const outbox = [];
  return {
    outbox,
    async send(mail) {
      outbox.push(mail);
      return 'msg-' + outbox.length;
    },
  };
}

